import { expect, test, type Page } from "@playwright/test";
import { label } from "../support/strings";

// The Movements grid over a period of five thousand movements, generated by
// the scenario ledger from `ledgerRows`: how long the first page takes to
// draw, to scroll to the end, to select every row and to filter, and that the
// page draws a window of rows, never all of them. Each timing is logged as a
// JSON line; the budgets are generous so that a loaded machine passes and
// only a change of kind fails.

const ROWS = 5_000;
const WINDOW_LIMIT = 80;

const page = (target: Page) => target.locator(".ledger-page");
const head = (target: Page) => target.locator(".pane-docs .pane-head");
const grid = (target: Page) => page(target).getByRole("grid");
const dataRows = (target: Page) => grid(target).locator("[data-kind=data]");
const count = (target: Page) => page(target).locator(".ledger-count");

/** What the toolbar says is shown: "8 of 40 movements". */
async function counts(target: Page): Promise<{ shown: number; total: number }> {
  const text = ((await count(target).textContent()) ?? "").split(" · ")[0]!;
  const numbers = [...text.matchAll(/\d[\d,]*/g)].map((found) =>
    Number(found[0].replace(/,/g, "")),
  );
  return { shown: numbers[0] ?? 0, total: numbers.at(-1) ?? 0 };
}

const total = async (target: Page) => (await counts(target)).total;

function logged(name: string, started: number) {
  const elapsed = Date.now() - started;
  console.log(JSON.stringify({ benchmark: name, elapsed_ms: elapsed }));
  return elapsed;
}

async function openFourthQuarter(target: Page) {
  await target.goto(
    `/scenarios.html?scenario=ledger&latency=0&bar=off&ledgerRows=${ROWS}`,
  );
  await target.locator("[data-rail=ledger]").click();
  await expect(grid(target)).toBeVisible();
  await head(target).locator(".ledger-period").click();
  const periods = target.getByRole("dialog", {
    name: label("desktop.ledger.period.choose"),
  });
  const shown = periods.locator("[aria-live=polite]");
  for (let guard = 0; guard < 40; guard += 1) {
    const at = Number(await shown.textContent());
    if (at === 2026) break;
    await periods
      .getByRole("button", {
        name: label(
          at > 2026
            ? "desktop.ledger.period.year_previous"
            : "desktop.ledger.period.year_next",
        ),
        exact: true,
      })
      .click();
  }
  const choice = periods
    .getByRole("group", {
      name: label("desktop.ledger.period.of_year", { year: 2026 }),
    })
    .getByRole("button", { name: "4T", exact: true });
  // The page is read from the choice to the first drawn row.
  const started = Date.now();
  await choice.click();
  await expect(dataRows(target).first()).toBeVisible({ timeout: 30_000 });
  return started;
}

test("five thousand movements draw, scroll, select and filter within budget", async ({
  page: target,
}) => {
  test.setTimeout(180_000);
  const started = await openFourthQuarter(target);
  expect(logged("ledger_first_page_drawn", started)).toBeLessThan(1_500);

  // The whole period is read before it is drawn as one: its count is exact.
  await expect.poll(() => total(target), { timeout: 60_000 }).toBe(ROWS);
  logged("ledger_period_read_whole", started);
  await expect(grid(target)).toHaveAttribute("aria-rowcount", String(ROWS + 1));
  expect(await dataRows(target).count()).toBeLessThan(WINDOW_LIMIT);

  // Scrolling to the last row draws it, and still only a window of rows.
  const scrolled = Date.now();
  await grid(target).evaluate((element) => {
    element.scrollTop = element.scrollHeight;
  });
  await expect(
    grid(target).locator(`[data-kind=data][aria-rowindex="${ROWS + 1}"]`),
  ).toBeVisible();
  expect(logged("ledger_scroll_to_end", scrolled)).toBeLessThan(1_000);
  expect(await dataRows(target).count()).toBeLessThan(WINDOW_LIMIT);

  // Select all marks every drawn row, and only a window of them is drawn.
  await dataRows(target).last().locator("[data-column=description]").click();
  const selected = Date.now();
  await target.keyboard.press("Control+KeyA");
  await expect(
    dataRows(target).last().and(target.locator("[aria-selected=true]")),
  ).toBeVisible();
  expect(logged("ledger_select_all", selected)).toBeLessThan(500);
  expect(await dataRows(target).count()).toBeLessThan(WINDOW_LIMIT);

  // A filter narrows the five thousand to the words' matches.
  const search = page(target).getByRole("searchbox", {
    name: label("desktop.ledger.search.label"),
  });
  const filtered = Date.now();
  await search.fill("farmacia");
  // Polled as often as a locator assertion retries: the default backoff of a
  // poll would add its own waits to the time measured.
  await expect
    .poll(async () => (await counts(target)).shown, { intervals: [20] })
    .toBeLessThan(ROWS);
  expect(logged("ledger_filter", filtered)).toBeLessThan(500);
  expect(await dataRows(target).count()).toBeLessThan(WINDOW_LIMIT);
  expect((await counts(target)).shown).toBeGreaterThan(0);
});
